let current: Lang = "en";
/** Set during App render so humanize() and other non-hook helpers follow the chosen language. */
export function setCurrentLang(l: Lang) { current = l; }
export function valueLabel(v: string): string | null {
  const e = V[v];
  return e ? e[{ en: 0, ta: 1, hi: 2 }[current]] || e[0] : null;
}
/** A translated string outside React components (same dictionary as useT). */
export function T(key: string, params?: Record<string, string | number>) { return translate(current, key, params); }

export function translate(lang: Lang, key: string, params?: Record<string, string | number>): string {
  const e = D[key];
  let s = e ? e[{ en: 0, ta: 1, hi: 2 }[lang]] || e[0] : key;
  for (const [k, v] of Object.entries(params ?? {})) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}

/** Keys missing a translation (the test suite keeps this empty). */
export function missingTranslations(): string[] {
  return [...Object.entries(D), ...Object.entries(V)].filter(([, e]) => e.length !== 3 || e.some((s) => !s)).map(([k]) => k);
}

export function loadLang(): Lang {
  try {
    const v = localStorage.getItem("p2e.lang");
    return v === "ta" || v === "hi" ? v : "en";
  } catch {
    return "en";
  }
}

export function saveLang(lang: Lang) {
  try { localStorage.setItem("p2e.lang", lang); } catch { /* ignore */ }
  if (typeof document !== "undefined") document.documentElement.lang = lang;
}

export const LangContext = createContext<{ lang: Lang; setLang: (l: Lang) => void }>({ lang: "en", setLang: () => {} });

export function useT() {
  const { lang, setLang } = useContext(LangContext);
  return { lang, setLang, t: (key: string, params?: Record<string, string | number>) => translate(lang, key, params),
    speech: LANGS.find((l) => l.code === lang)!.speech };
}
